list_order_flags.code:
const response = await client.orderFlags.listOrderFlags({limit: 20});
for (const orderFlag of response.map.order_flags) {
    console.log(orderFlag.id, orderFlag.name, orderFlag.color);
}

create_order_flag.code:
const response = await client.orderFlags.createOrderFlag({
    order_flag: {name: 'Awaiting Stock', color: '#5A7BD4', description: 'Waiting for stock to arrive.'},
});
console.log(response.map.order_flag.id);

